from httpbin.core import app
client = app.test_client()

def test_get_response_contains_required_top_level_keys():
    r = client.get('/get?x=1')
    assert r.status_code == 200
    body = r.get_json()
    assert set(body.keys()) == {'url', 'args', 'headers', 'origin'}
    assert body['args']['x'] == '1'
    assert body['args'] == {'x': '1'}

test_get_response_contains_required_top_level_keys()
